/**
 * Mastery tier-57 feature gates.
 * Closed when getMasteryBonus is missing, so tests and partial mocks stay locked.
 */

export type MasteryFeatureId =
  | 'pension_optimizer'
  | 'mass_prestige'
  | 'auto_prestige_alloc'
  | 'auto_expedition_relaunch';

export type MasteryFeatureIntroFlag =
  | 'pensionOptimizerIntroShown'
  | 'massPrestigeIntroShown'
  | 'autoPrestigeAllocIntroShown'
  | 'autoExpeditionRelaunchIntroShown';

const BONUS_BY_FEATURE: Record<MasteryFeatureId, string> = {
  pension_optimizer: 'pension_optimizer',
  mass_prestige: 'mass_prestige',
  auto_prestige_alloc: 'auto_prestige_alloc',
  auto_expedition_relaunch: 'auto_expedition_relaunch',
};

export interface MasteryFeatureHost {
  getMasteryBonus?: (bonusType: string) => number;
}

export function isMasteryFeatureUnlocked(
  game: MasteryFeatureHost | null | undefined,
  feature: MasteryFeatureId,
): boolean {
  if (!game || typeof game.getMasteryBonus !== 'function') return false;
  return (Number(game.getMasteryBonus(BONUS_BY_FEATURE[feature])) || 0) > 0;
}
